const std = @import("std");
const testing = std.testing;

// ============================================================================
// decodeResync tests (full-snapshot reconciliation, schema 5.0.8 port)
//
// Byte fixtures generated by schema-5.0
// test-external/generate-resync-fixtures.ts — each fixture is self-verified
// against the 5.0 JS Decoder before being printed.
// Contract: PORTING_RESYNC.md / test/ResyncSweep.test.ts.
// ============================================================================

const c = @cImport({
    @cInclude("colyseus/schema/types.h");
    @cInclude("colyseus/schema/collections.h");
    @cInclude("colyseus/schema/ref_tracker.h");
    @cInclude("colyseus/schema/decoder.h");
    @cInclude("schema/resync_state.h");
    @cInclude("schema/resync_array_state.h");
    @cInclude("schema/resync_state_v1.h");
    @cInclude("schema/resync_transient_state.h");
});

// ============================================================================
// Helpers
// ============================================================================

fn decode(decoder: *c.colyseus_decoder_t, bytes: []const u8) void {
    var it = c.colyseus_iterator_t{ .offset = 0 };
    c.colyseus_decoder_decode(decoder, bytes.ptr, bytes.len, &it);
}

fn decodeResync(decoder: *c.colyseus_decoder_t, bytes: []const u8) void {
    var it = c.colyseus_iterator_t{ .offset = 0 };
    c.colyseus_decoder_decode_resync(decoder, bytes.ptr, bytes.len, &it);
}

fn unitAt(map: [*c]c.colyseus_map_schema_t, key: [*c]const u8) ?*c.unit_t {
    const ptr = c.colyseus_map_schema_get(map, key);
    if (ptr == null) return null;
    return @ptrCast(@alignCast(ptr));
}

fn treeAt(map: [*c]c.colyseus_map_schema_t, key: [*c]const u8) ?f64 {
    const ptr = c.colyseus_map_schema_get(map, key);
    if (ptr == null) return null;
    const v: *f64 = @ptrCast(@alignCast(ptr));
    return v.*;
}

fn gemPriceAt(arr: [*c]c.colyseus_array_schema_t, index: c_int) f64 {
    const gem: *c.gem_t = @ptrCast(@alignCast(c.colyseus_array_schema_get(arr, index).?));
    return gem.price;
}

fn refsCount(decoder: *c.colyseus_decoder_t) usize {
    return c.colyseus_ref_tracker_count(decoder.refs);
}

// ============================================================================
// scenarios
// ============================================================================

test "resync_ghost_map" {
    const decoder = c.colyseus_decoder_create(&c.resync_state_vtable).?;
    defer c.colyseus_decoder_free(decoder);

    decode(decoder, &[_]u8{ 128, 1, 129, 2, 255, 1, 128, 0, 162, 101, 49, 3, 128, 1, 162, 101, 50, 5, 255, 3, 128, 163, 111, 110, 101, 129, 100, 130, 4, 255, 5, 128, 163, 116, 119, 111, 129, 100, 130, 6 });

    const state: *c.resync_state_t = @ptrCast(@alignCast(c.colyseus_decoder_get_state(decoder)));
    try testing.expectEqual(@as(c_int, 2), state.units.*.count);

    // offline: e2 died; its DELETE patch was never delivered
    decodeResync(decoder, &[_]u8{ 128, 1, 129, 2, 255, 1, 128, 0, 162, 101, 49, 3, 255, 3, 128, 163, 111, 110, 101, 129, 100, 130, 4 });

    try testing.expectEqual(@as(c_int, 1), state.units.*.count);
    try testing.expect(unitAt(state.units, "e1") != null);
    try testing.expect(unitAt(state.units, "e2") == null);
    try testing.expectEqual(@as(usize, 5), refsCount(decoder));
}

test "resync_prune_primitive_map" {
    const decoder = c.colyseus_decoder_create(&c.resync_state_vtable).?;
    defer c.colyseus_decoder_free(decoder);

    decode(decoder, &[_]u8{ 128, 1, 129, 2, 255, 2, 128, 0, 162, 116, 49, 10, 128, 1, 162, 116, 50, 20, 128, 2, 162, 116, 51, 30 });

    const state: *c.resync_state_t = @ptrCast(@alignCast(c.colyseus_decoder_get_state(decoder)));
    try testing.expectEqual(@as(c_int, 3), state.trees.*.count);

    decodeResync(decoder, &[_]u8{ 128, 1, 129, 2, 255, 2, 128, 0, 162, 116, 49, 10, 128, 2, 162, 116, 51, 30 });

    try testing.expectEqual(@as(c_int, 2), state.trees.*.count);
    try testing.expectEqual(@as(f64, 10), treeAt(state.trees, "t1").?);
    try testing.expect(treeAt(state.trees, "t2") == null);
    try testing.expectEqual(@as(f64, 30), treeAt(state.trees, "t3").?);
}

test "resync_nested_collection" {
    const decoder = c.colyseus_decoder_create(&c.resync_state_vtable).?;
    defer c.colyseus_decoder_free(decoder);

    decode(decoder, &[_]u8{ 128, 1, 129, 2, 255, 1, 128, 0, 164, 104, 101, 114, 111, 3, 255, 3, 128, 164, 104, 101, 114, 111, 129, 100, 130, 4, 255, 4, 128, 0, 5, 128, 1, 6, 128, 2, 7, 255, 5, 128, 0, 255, 6, 128, 1, 255, 7, 128, 2 });

    const state: *c.resync_state_t = @ptrCast(@alignCast(c.colyseus_decoder_get_state(decoder)));
    const hero_before = unitAt(state.units, "hero").?;

    // offline: hero lost the middle gem
    decodeResync(decoder, &[_]u8{ 128, 1, 129, 2, 255, 1, 128, 0, 164, 104, 101, 114, 111, 3, 255, 3, 128, 164, 104, 101, 114, 111, 129, 100, 130, 4, 255, 4, 128, 0, 5, 128, 1, 7, 255, 5, 128, 0, 255, 7, 128, 2 });

    const hero_after = unitAt(state.units, "hero").?;
    try testing.expectEqual(hero_before, hero_after); // retained parent keeps identity
    try testing.expectEqual(@as(c_int, 2), hero_after.gems.*.count);
    try testing.expectEqual(@as(f64, 0), gemPriceAt(hero_after.gems, 0));
    try testing.expectEqual(@as(f64, 2), gemPriceAt(hero_after.gems, 1));
}

test "resync_view_interior" {
    // snapshots are view-encoded (ADD_BY_REFID ops)
    const decoder = c.colyseus_decoder_create(&c.resync_array_state_vtable).?;
    defer c.colyseus_decoder_free(decoder);

    decode(decoder, &[_]u8{ 255, 0, 128, 1, 255, 1, 129, 2, 2, 129, 4, 4, 129, 6, 6, 255, 2, 128, 161, 97, 129, 100, 130, 3, 255, 4, 128, 161, 98, 129, 100, 130, 5, 255, 6, 128, 161, 99, 129, 100, 130, 7 });

    const state: *c.resync_array_state_t = @ptrCast(@alignCast(c.colyseus_decoder_get_state(decoder)));
    try testing.expectEqual(@as(c_int, 3), state.arr.*.count);

    // offline: b left the view — an interior index, not the tail
    decodeResync(decoder, &[_]u8{ 255, 0, 128, 1, 255, 1, 129, 2, 2, 129, 6, 6, 255, 2, 128, 161, 97, 129, 100, 130, 3, 255, 6, 128, 161, 99, 129, 100, 130, 7 });

    try testing.expectEqual(@as(c_int, 2), state.arr.*.count);
    const first: *c.unit_t = @ptrCast(@alignCast(c.colyseus_array_schema_get(state.arr, 0).?));
    const second: *c.unit_t = @ptrCast(@alignCast(c.colyseus_array_schema_get(state.arr, 1).?));
    try testing.expectEqualStrings("a", std.mem.span(first.name));
    try testing.expectEqualStrings("c", std.mem.span(second.name));
}

